"""
Human Beta-Globin (HBB) UTR Sequences from NM_000518.6

Reference: NCBI RefSeq NM_000518.6 (Homo sapiens hemoglobin subunit beta)
https://www.ncbi.nlm.nih.gov/nuccore/NM_000518.6

These sequences are used as default therapeutically relevant UTRs for the miRNA switch platform.

IMPORTANT USAGE NOTES:
1. RNA Sequences (with 'U'): Used for computational analysis of miRNA binding, 
   RNA structure prediction, and accessibility calculations. These should be 
   used with off_target_check.py and accessibility_predictor.py.

2. DNA Sequences (with 'T'): Used for actual therapeutic design, cloning,
   and insertion into plasmids/vectors. These should be used when designing
   constructs for experimental validation.
"""

# ====== RNA SEQUENCES (for computational analysis) ======

# 5' UTR sequence (RNA version - for computational analysis)
HBB_5UTR_RNA = "ACAUUUGCUUCUGACACAACUGUGUUCACUAGCAACCUCAAACAGACACC"

# 3' UTR sequence (RNA version - for computational analysis)
HBB_3UTR_RNA = ""

# Poly(A) signal is "AAUAAA" near the end of the 3' UTR (positions 166-171 from the start of the 3' UTR)
HBB_3UTR_RNA_WITH_POLYA = HBB_3UTR_RNA[0:171]  # Up to and including the poly(A) signal

# Shorter version of the 3' UTR focused on the commonly used region (RNA version)
HBB_3UTR_RNA_SHORT = "AUGGUGCAUCUGACUCCUGAGGAGAAGUCUGCCGUUACUGCCCUGUGGGGCAAGGUGAACGUGGAUGAAGUUGGUGGUGAGGCCCUGGGCAGGCUGCUGGUGGUGUACCCUUGGACCCAGAGGUUCUUUGAGUCCUUUGGGAUCUGUCCACUCCUGAUGCUGUUAUGGGCAACCCUAAGGUGAAGGCUCAUGGCAAGAAAG"

# ====== DNA SEQUENCES (for plasmid/vector design) ======

# 5' UTR sequence (DNA version - for plasmid design)
HBB_5UTR_DNA = "ACATTTGCTTCTGACACAACTGTGTTCACTAGCAACCTCAAACAGACACC"

