HBB_3UTR_DNA_WITH_POLYA = HBB_3UTR_DNA[0:171]  # Up to and including the poly(A) signal

# Shorter version of the 3' UTR focused on the commonly used region (DNA version)
HBB_3UTR_DNA_SHORT = "ATGGTGCATCTGACTCCTGAGGAGAAGTCTGCCGTTACTGCCCTGTGGGGCAAGGTGAACGTGGATGAAGTTGGTGGTGAGGCCCTGGGCAGGCTGCTGGTGGTGTACCCTTGGACCCAGAGGTTCTTTGAGTCCTTTGGGGATCTGTCCACTCCTGATGCTGTTATGGGCAACCCTAAGGTGAAGGCTCATGGCAAGAAAG"

